const item = $input.first();
const secret = (item.json.headers || {})['x-ray-secret'];
if (secret !== "SET_MARKETING_WEBHOOK_SECRET") {
  throw new Error('Unauthorized: token rahasia tidak cocok');
}
const b = item.json.body || {};
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const ymd = now.getFullYear() + pad(now.getMonth() + 1) + pad(now.getDate());
const rnd3 = String(Math.floor(Math.random() * 900) + 100);
const research_id = /^RK-[0-9a-f-]{36}$/i.test(String(b.research_id || '')) ? String(b.research_id) : 'SEARCH-' + ymd + '-' + rnd3;
const tanggal = now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());

const type = String(b.target_type || '').toUpperCase();
const kecamatan = String(b.kecamatan || '').trim();
const kabupaten_kota = String(b.kabupaten_kota || '').trim();
const provinsi = String(b.provinsi || '').trim();
const bidang = String(b.bidang || '').trim();
const jumlahNum = parseInt(b.jumlah, 10);

const missing = [];
if (type !== 'SWASTA' && type !== 'PEMERINTAH') missing.push('target_type');
if (!kecamatan) missing.push('kecamatan');
if (!kabupaten_kota) missing.push('kabupaten_kota');
if (!provinsi) missing.push('provinsi');
if (type === 'SWASTA' && !bidang) missing.push('bidang');
if (!Number.isFinite(jumlahNum) || jumlahNum <= 0) missing.push('jumlah');

return [{
  json: {
    valid: missing.length === 0,
    missing,
    chat_id: 'rayai',
    target_type: type,
    kecamatan, kabupaten_kota, provinsi, bidang,
    jumlah: Math.min(Number.isFinite(jumlahNum) ? jumlahNum : 0, 10),
    research_id, tanggal, drive_folder_id: String(b.drive_folder_id || '')
  }
}];

