const p = $('Siapkan Data Target (RAY AI)').first().json;
const agent = ($input.first().json && $input.first().json.output) || {};
const targets = Array.isArray(agent.targets) ? agent.targets : [];
const seed = Date.now() % 1000000;
const catOf = (s) => { const n = Number(s) || 0; return n >= 80 ? 'HOT' : n >= 60 ? 'WARM' : n >= 40 ? 'POTENTIAL' : 'LOW'; };
const NF = 'Belum ditemukan';
const phoneVal = (v) => { const s = val(v); return s === NF ? NF : String.fromCharCode(39) + s; };
const val = (v) => { const s = (v == null ? '' : String(v)).trim(); return s === '' ? NF : s; };

if (!targets.length) { return [{json:{_no_target:true}}]; }

return targets.map((t, idx) => {
  const leadNum = String((seed + idx) % 1000000).padStart(6, '0');
  const score = Number(t.lead_score) || 0;
  return {
    json: {
      lead_id: 'RMP-2026-' + leadNum,
      research_id: p.research_id,
      tanggal: p.tanggal,
      target_type: p.target_type,
      nama_target: val(t.nama_target),
      jenis: val(t.jenis),
      bidang: p.target_type === 'SWASTA' ? p.bidang : 'Pemerintah',
      kecamatan: val(t.kecamatan) === NF ? p.kecamatan : t.kecamatan,
      kabupaten_kota: val(t.kabupaten_kota) === NF ? p.kabupaten_kota : t.kabupaten_kota,
      provinsi: val(t.provinsi) === NF ? p.provinsi : t.provinsi,
      alamat: val(t.alamat),
      telepon: phoneVal(t.telepon),
      nomor_profesional: phoneVal(t.nomor_profesional),
      email: val(t.email),
      website: val(t.website),
      direktur: val(t.direktur),
      hrd: val(t.hrd),
      hrga: val(t.hrga),
      general_affairs: val(t.general_affairs),
      procurement: val(t.procurement),
      kepala_dinas: val(t.kepala_dinas),
      sekretaris: val(t.sekretaris),
      kabag_umum: val(t.kabag_umum),
      kasubbag_umum: val(t.kasubbag_umum),
      bagian_pengadaan: val(t.bagian_pengadaan),
      procurement_ppk: val(t.procurement_ppk),
      potensi_outsourcing: val(t.potensi_outsourcing),
      procurement_paket: val(t.procurement_paket),
      procurement_jenis: val(t.procurement_jenis),
      procurement_tahun: val(t.procurement_tahun),
      procurement_pagu: val(t.procurement_pagu),
      procurement_volume: val(t.procurement_volume),
      procurement_idrup: val(t.procurement_idrup),
      satker: val(t.satker),
      procurement_link: val(t.procurement_link),
      sumber: val(t.sumber),
      lead_score: score,
      kategori: catOf(score)
    }
  };
});

